#include <bits/stdc++.h>
using namespace std;
const long long MOD = 1000000007;
int main(){
    int n, m;
    cin >> n >> m;
    vector<vector<pair<int,long long>>> adj(n+1);
    for(int i=0;i<m;i++){
        int u,v; long long w;
        cin >> u >> v >> w;
        adj[u].push_back({v,w});
    }
    vector<long long> dist(n+1, LLONG_MAX);
    vector<long long> cnt(n+1, 0);
    dist[1]=0; cnt[1]=1;
    priority_queue<pair<long long,int>, vector<pair<long long,int>>, greater<>> pq;
    pq.push({0,1});
    while(!pq.empty()){
        auto [d,u] = pq.top(); pq.pop();
        if(d > dist[u]) continue; // stale entry
        for(auto [v,w] : adj[u]){
            long long nd = d + w;
            if(nd < dist[v]){
                dist[v] = nd;
                cnt[v] = cnt[u] % MOD;
                pq.push({nd, v});
            } else if(nd == dist[v]){
                cnt[v] = (cnt[v] + cnt[u]) % MOD;
            }
        }
    }
    cout << dist[n] << " " << cnt[n] << "\n";
}

#include <bits/stdc++.h>
using namespace std;
const long long NEG_INF = LLONG_MIN / 2;
int main(){
    int n, m;
    cin >> n >> m;
    vector<array<long long,3>> edges(m); // u, v, w
    for(int i=0;i<m;i++){
        long long u,v,w; cin >> u >> v >> w;
        edges[i] = {u,v,w};
    }
    vector<long long> dist(n+1, NEG_INF);
    dist[1] = 0;
    // n-1 passes guarantee correct longest-path values in absence of positive cycles
    for(int i=0;i<n-1;i++){
        for(auto &e : edges){
            int u=e[0], v=e[1]; long long w=e[2];
            if(dist[u] > NEG_INF/2 && dist[u]+w > dist[v]) dist[v] = dist[u]+w;
        }
    }
    vector<char> unbounded(n+1, 0);
    // propagate: one more relaxation pass detects nodes still improvable (on/after a positive cycle);
    // repeat n times so the "unbounded" property propagates along any chain of edges of length < n
    for(int i=0;i<n;i++){
        for(auto &e : edges){
            int u=e[0], v=e[1]; long long w=e[2];
            if(dist[u] <= NEG_INF/2) continue;
            if(dist[u] + w > dist[v] || unbounded[u]){
                if(dist[u]+w > dist[v]) dist[v] = dist[u]+w;
                unbounded[v] = 1;
            }
        }
    }
    if(unbounded[n]) cout << "IMPOSSIBLE\n";
    else cout << dist[n] << "\n";
}

#include <bits/stdc++.h>
using namespace std;
const long long INF = LLONG_MAX/4;
int main(){
    int n, m; long long s, t;
    cin >> n >> m >> s >> t;
    vector<vector<long long>> d(n+1, vector<long long>(n+1, INF));
    for(int i=1;i<=n;i++) d[i][i]=0;
    vector<array<long long,3>> edges(m);
    for(int i=0;i<m;i++){
        long long a,b,w; cin >> a >> b >> w;
        edges[i]={a,b,w};
        d[a][b] = min(d[a][b], w);
        d[b][a] = min(d[b][a], w);
    }
    for(int k=1;k<=n;k++)
        for(int i=1;i<=n;i++)
            for(int j=1;j<=n;j++)
                if(d[i][k]+d[k][j] < d[i][j]) d[i][j] = d[i][k]+d[k][j];

    long long best = d[s][t];
    for(auto &e : edges){
        long long a=e[0], b=e[1], w=e[2];
        long long half = w/2; // weights are given even, so this is exact
        best = min(best, d[s][a] + half + d[b][t]);
        best = min(best, d[s][b] + half + d[a][t]);
    }
    cout << best << "\n";
}

#include <bits/stdc++.h>
using namespace std;
struct DSU{
    vector<int> p, r;
    DSU(int n): p(n+1), r(n+1,0){ iota(p.begin(), p.end(), 0); }
    int find(int x){ return p[x]==x ? x : p[x]=find(p[x]); }
    bool unite(int a, int b){
        a=find(a); b=find(b);
        if(a==b) return false;
        if(r[a]<r[b]) swap(a,b);
        p[b]=a;
        if(r[a]==r[b]) r[a]++;
        return true;
    }
};
int main(){
    int n, m;
    cin >> n >> m;
    vector<array<long long,3>> edges(m);
    for(int i=0;i<m;i++){
        long long a,b,w; cin >> a >> b >> w;
        edges[i] = {w,a,b};
    }
    sort(edges.begin(), edges.end());
    DSU dsu(n);
    long long total = 0;
    int used = 0;
    for(auto &e : edges){
        long long w=e[0], a=e[1], b=e[2];
        if(dsu.unite(a,b)){
            total += w;
            used++;
        }
    }
    if(used == n-1) cout << total << "\n";
    else cout << "IMPOSSIBLE\n";
}

#include <bits/stdc++.h>
using namespace std;
const long long INF = LLONG_MAX/4;
int main(){
    int n, m;
    cin >> n >> m;
    vector<vector<long long>> g(n+1, vector<long long>(n+1, INF));
    for(int i=0;i<m;i++){
        int a,b; long long w;
        cin >> a >> b >> w;
        g[a][b] = min(g[a][b], w);
        g[b][a] = min(g[b][a], w);
    }
    vector<long long> minEdge(n+1, INF);
    vector<char> inMST(n+1, 0);
    minEdge[1] = 0;
    long long total = 0;
    int count = 0;
    for(int iter=0; iter<n; iter++){
        int u = -1;
        for(int v=1; v<=n; v++){
            if(!inMST[v] && (u==-1 || minEdge[v] < minEdge[u])) u = v;
        }
        if(minEdge[u] == INF){ count = -1; break; } // unreachable -> not connected
        inMST[u] = 1;
        total += minEdge[u];
        count++;
        for(int v=1; v<=n; v++){
            if(!inMST[v] && g[u][v] < minEdge[v]) minEdge[v] = g[u][v];
        }
    }
    if(count == n) cout << total << "\n";
    else cout << "IMPOSSIBLE\n";
}

#include <bits/stdc++.h>
using namespace std;
struct DSU{
    vector<int> p, r;
    DSU(int n): p(n+1), r(n+1,0){ iota(p.begin(), p.end(), 0); }
    int find(int x){ return p[x]==x ? x : p[x]=find(p[x]); }
    bool unite(int a, int b){
        a=find(a); b=find(b);
        if(a==b) return false;
        if(r[a]<r[b]) swap(a,b);
        p[b]=a;
        if(r[a]==r[b]) r[a]++;
        return true;
    }
};
int main(){
    int n, m;
    cin >> n >> m;
    // store as (w, a, b) plus original index
    vector<array<long long,3>> edges(m);
    for(int i=0;i<m;i++){
        long long a,b,w; cin >> a >> b >> w;
        edges[i] = {w,a,b};
    }
    // sorted order of edge indices by weight, used for every query
    vector<int> order(m);
    iota(order.begin(), order.end(), 0);
    sort(order.begin(), order.end(), [&](int i, int j){ return edges[i][0] < edges[j][0]; });

    vector<long long> answers(m);
    for(int q=0; q<m; q++){
        DSU dsu(n);
        long long total = edges[q][0];
        dsu.unite((int)edges[q][1], (int)edges[q][2]);
        int used = 1;
        for(int idx : order){
            if(idx == q) continue;
            long long w=edges[idx][0], a=edges[idx][1], b=edges[idx][2];
            if(dsu.unite((int)a,(int)b)){
                total += w;
                used++;
            }
        }
        answers[q] = (used == n-1) ? total : -1; // -1 would mean graph disconnected without this edge helping
    }
    for(int i=0;i<m;i++){
        cout << answers[i] << (i+1<m ? ' ' : '\n');
    }
}

#include <bits/stdc++.h>
using namespace std;
int main(){
    int n, m;
    cin >> n >> m;
    vector<vector<int>> adj(n+1);
    vector<int> indeg(n+1, 0);
    for(int i=0;i<m;i++){
        int u,v; cin >> u >> v;
        adj[u].push_back(v);
        indeg[v]++;
    }
    priority_queue<int, vector<int>, greater<int>> pq; // smallest label first -> deterministic order
    for(int v=1; v<=n; v++) if(indeg[v]==0) pq.push(v);
    vector<int> order;
    while(!pq.empty()){
        int u = pq.top(); pq.pop();
        order.push_back(u);
        for(int v : adj[u]){
            if(--indeg[v]==0) pq.push(v);
        }
    }
    if((int)order.size() != n){
        cout << "IMPOSSIBLE\n";
    } else {
        for(int i=0;i<n;i++) cout << order[i] << (i+1<n?' ':'\n');
    }
}

#include <bits/stdc++.h>
using namespace std;
int n, m;
vector<vector<int>> adj;
vector<int> color_; // 0 = white (unvisited), 1 = gray (on stack), 2 = black (done)
vector<int> postorder;
bool cyclic = false;

void dfs(int u){
    color_[u] = 1; // gray: currently in the recursion stack
    for(int v : adj[u]){
        if(cyclic) return;
        if(color_[v] == 1){
            cyclic = true; // back edge to an ancestor -> cycle
            return;
        }
        if(color_[v] == 0) dfs(v);
    }
    color_[u] = 2; // black: fully explored
    postorder.push_back(u);
}

int main(){
    cin >> n >> m;
    adj.assign(n+1, {});
    color_.assign(n+1, 0);
    for(int i=0;i<m;i++){
        int u,v; cin >> u >> v;
        adj[u].push_back(v);
    }
    for(int s=1; s<=n && !cyclic; s++){
        if(color_[s]==0) dfs(s);
    }
    if(cyclic){
        cout << "IMPOSSIBLE\n";
    } else {
        reverse(postorder.begin(), postorder.end());
        for(int i=0;i<n;i++) cout << postorder[i] << (i+1<n?' ':'\n');
    }
}

#include <bits/stdc++.h>
using namespace std;
const long long NEG_INF = LLONG_MIN/2;
int main(){
    int n, m, src, dst;
    cin >> n >> m >> src >> dst;
    vector<vector<pair<int,long long>>> adj(n+1);
    vector<int> indeg(n+1, 0);
    for(int i=0;i<m;i++){
        int u,v; long long w;
        cin >> u >> v >> w;
        adj[u].push_back({v,w});
        indeg[v]++;
    }
    queue<int> q;
    for(int v=1; v<=n; v++) if(indeg[v]==0) q.push(v);
    vector<int> topo;
    vector<int> indeg2 = indeg;
    while(!q.empty()){
        int u = q.front(); q.pop();
        topo.push_back(u);
        for(auto &pr : adj[u]){
            int v = pr.first;
            if(--indeg2[v]==0) q.push(v);
        }
    }
    vector<long long> dist(n+1, NEG_INF);
    dist[src] = 0;
    for(int u : topo){
        if(dist[u] == NEG_INF) continue;
        for(auto &pr : adj[u]){
            int v = pr.first; long long w = pr.second;
            if(dist[u] + w > dist[v]) dist[v] = dist[u] + w;
        }
    }
    if(dist[dst] == NEG_INF) cout << "UNREACHABLE\n";
    else cout << dist[dst] << "\n";
}

#include <bits/stdc++.h>
using namespace std;
int n, m, timer_ = 0;
vector<vector<int>> adj;
vector<int> disc, low;
vector<char> onStack;
vector<int> st;
vector<vector<int>> sccs;

void dfs(int u){
    disc[u] = low[u] = timer_++;
    st.push_back(u);
    onStack[u] = 1;
    for(int v : adj[u]){
        if(disc[v] == -1){
            dfs(v);
            low[u] = min(low[u], low[v]);
        } else if(onStack[v]){
            low[u] = min(low[u], disc[v]);
        }
    }
    if(low[u] == disc[u]){
        vector<int> comp;
        while(true){
            int w = st.back(); st.pop_back();
            onStack[w] = 0;
            comp.push_back(w);
            if(w == u) break;
        }
        sort(comp.begin(), comp.end());
        sccs.push_back(comp);
    }
}

int main(){
    cin >> n >> m;
    adj.assign(n+1, {});
    disc.assign(n+1, -1);
    low.assign(n+1, 0);
    onStack.assign(n+1, 0);
    for(int i=0;i<m;i++){
        int u,v; cin >> u >> v;
        adj[u].push_back(v);
    }
    for(int s=1;s<=n;s++) if(disc[s]==-1) dfs(s);

    cout << sccs.size() << "\n";
    for(auto &c : sccs){
        for(size_t i=0;i<c.size();i++) cout << c[i] << (i+1<c.size() ? ' ' : '\n');
    }
}

#include <bits/stdc++.h>
using namespace std;
int n, m, timer_ = 0, capital;
vector<vector<int>> adj;
vector<int> disc, low, comp;
vector<char> onStack;
vector<int> st;
int numComp = 0;

void dfs(int u){
    disc[u] = low[u] = timer_++;
    st.push_back(u);
    onStack[u] = 1;
    for(int v : adj[u]){
        if(disc[v] == -1){
            dfs(v);
            low[u] = min(low[u], low[v]);
        } else if(onStack[v]){
            low[u] = min(low[u], disc[v]);
        }
    }
    if(low[u] == disc[u]){
        while(true){
            int w = st.back(); st.pop_back();
            onStack[w] = 0;
            comp[w] = numComp;
            if(w == u) break;
        }
        numComp++;
    }
}

int main(){
    cin >> n >> m >> capital;
    adj.assign(n+1, {});
    disc.assign(n+1, -1);
    low.assign(n+1, 0);
    onStack.assign(n+1, 0);
    comp.assign(n+1, -1);
    vector<pair<int,int>> edges(m);
    for(int i=0;i<m;i++){
        int u,v; cin >> u >> v;
        edges[i] = {u,v};
        adj[u].push_back(v);
    }
    for(int s=1;s<=n;s++) if(disc[s]==-1) dfs(s);

    vector<int> indeg(numComp, 0);
    set<pair<int,int>> condEdges;
    for(auto &e : edges){
        int cu = comp[e.first], cv = comp[e.second];
        if(cu != cv) condEdges.insert({cu,cv});
    }
    for(auto &e : condEdges) indeg[e.second]++;

    int capComp = comp[capital];
    int answer = 0;
    for(int c=0;c<numComp;c++){
        if(c != capComp && indeg[c]==0) answer++;
    }
    cout << answer << "\n";
}

#include <bits/stdc++.h>
using namespace std;
int n, m, timer_ = 0;
vector<vector<pair<int,int>>> adj; // (neighbor, edge id)
vector<int> disc, low;
vector<pair<int,int>> bridges;

void dfs(int u, int parentEdge){
    disc[u] = low[u] = timer_++;
    for(auto &[v, id] : adj[u]){
        if(id == parentEdge) continue; // don't walk back along the edge we arrived on
        if(disc[v] == -1){
            dfs(v, id);
            low[u] = min(low[u], low[v]);
            if(low[v] > disc[u]){
                bridges.push_back({min(u,v), max(u,v)});
            }
        } else {
            low[u] = min(low[u], disc[v]); // back edge: use disc[v], not low[v]
        }
    }
}

int main(){
    cin >> n >> m;
    adj.assign(n+1, {});
    disc.assign(n+1, -1);
    low.assign(n+1, 0);
    for(int i=0;i<m;i++){
        int u,v; cin >> u >> v;
        adj[u].push_back({v,i});
        adj[v].push_back({u,i});
    }
    for(int s=1;s<=n;s++) if(disc[s]==-1) dfs(s, -1);

    sort(bridges.begin(), bridges.end());
    cout << bridges.size() << "\n";
    for(auto &[a,b] : bridges) cout << a << " " << b << "\n";
}

#include <bits/stdc++.h>
using namespace std;
int n, m, timer_ = 0;
vector<vector<pair<int,int>>> adj; // (neighbor, edge id)
vector<int> disc, low;
vector<char> isAP;

void dfs(int u, int parentEdge, bool isRoot){
    disc[u] = low[u] = timer_++;
    int children = 0;
    for(auto &[v, id] : adj[u]){
        if(id == parentEdge) continue;
        if(disc[v] == -1){
            children++;
            dfs(v, id, false);
            low[u] = min(low[u], low[v]);
            if(!isRoot && low[v] >= disc[u]) isAP[u] = 1;
        } else {
            low[u] = min(low[u], disc[v]);
        }
    }
    if(isRoot && children >= 2) isAP[u] = 1;
}

int main(){
    cin >> n >> m;
    adj.assign(n+1, {});
    disc.assign(n+1, -1);
    low.assign(n+1, 0);
    isAP.assign(n+1, 0);
    for(int i=0;i<m;i++){
        int u,v; cin >> u >> v;
        adj[u].push_back({v,i});
        adj[v].push_back({u,i});
    }
    for(int s=1;s<=n;s++) if(disc[s]==-1) dfs(s, -1, true);

    vector<int> result;
    for(int v=1;v<=n;v++) if(isAP[v]) result.push_back(v);
    cout << result.size() << "\n";
    for(size_t i=0;i<result.size();i++) cout << result[i] << (i+1<result.size()?' ':'\n');
}

#include <bits/stdc++.h>
using namespace std;
int n, m, timer_ = 0;
vector<vector<pair<int,int>>> adj; // (neighbor, edge id)
vector<int> disc, low;
vector<char> isBridge;
vector<pair<int,int>> edgeList;

void dfs(int u, int parentEdge){
    disc[u] = low[u] = timer_++;
    for(auto &[v, id] : adj[u]){
        if(id == parentEdge) continue;
        if(disc[v] == -1){
            dfs(v, id);
            low[u] = min(low[u], low[v]);
            if(low[v] > disc[u]) isBridge[id] = 1;
        } else {
            low[u] = min(low[u], disc[v]);
        }
    }
}

struct DSU{
    vector<int> p;
    DSU(int n): p(n+1){ iota(p.begin(), p.end(), 0); }
    int find(int x){ return p[x]==x ? x : p[x]=find(p[x]); }
    void unite(int a, int b){ a=find(a); b=find(b); if(a!=b) p[a]=b; }
};

int main(){
    cin >> n >> m;
    adj.assign(n+1, {});
    disc.assign(n+1, -1);
    low.assign(n+1, 0);
    isBridge.assign(m, 0);
    edgeList.resize(m);
    for(int i=0;i<m;i++){
        int u,v; cin >> u >> v;
        edgeList[i] = {u,v};
        adj[u].push_back({v,i});
        adj[v].push_back({u,i});
    }
    for(int s=1;s<=n;s++) if(disc[s]==-1) dfs(s, -1);

    DSU dsu(n);
    for(int i=0;i<m;i++){
        if(!isBridge[i]) dsu.unite(edgeList[i].first, edgeList[i].second);
    }
    set<int> roots;
    for(int v=1; v<=n; v++) roots.insert(dsu.find(v));
    cout << roots.size() << "\n";
}

